  e record; v_target_variant_id bigint; v_rows integer; v_mapping_before jsonb; v_offer_before jsonb;
  v_products_before bigint; v_variants_before bigint; v_mappings_before bigint; v_offers_before bigint; v_history_before bigint; v_series_before bigint;
begin
  if current_user<>'postgres' or v_target->>'target_environment'<>'PRODUCTION'
    or v_target->>'project_ref'<>'aftboxmrdgyhizicfsfu' or v_target->>'database_identity'<>'supplementscout-production:aftboxmrdgyhizicfsfu'
    or v_authority<>'owner-chat-2026-08-26-approved-fit-house-exact-pack-24-pack-count-1'
    or v_config_sha256<>'69316475e96e470840874a2eeeffa7f4a19319a437e6d947da101c4668267fb7'
    or v_manifest_sha256<>'a1e596f7707c851534e04e30d13f4289439449556787c572736e77b279c75292'
    or v_source_fingerprint<>'ef14011b0634d3f20053a569323eb8170defb458d28d22b1bbf700ef2416f1bb' then raise exception 'Fit House owner-reviewed exact-pack 24 authority, evidence or target mismatch'; end if;
  if jsonb_array_length(v_scope)<>24 or (select count(*) from jsonb_array_elements(v_scope) x where x->>'mode'='create')<>22
    or (select count(*) from jsonb_array_elements(v_scope) x where x->>'mode'='enrich')<>2
    or (select count(distinct (x->>'mapping_id')::bigint) from jsonb_array_elements(v_scope) x)<>24
    or exists(select 1 from jsonb_array_elements(v_scope) x where (x->>'mapping_id')::bigint in (686,687,869,870,874,2063,2084,2095,2096,2099,2107,2123)) then raise exception 'Fit House owner-reviewed exact-pack 24 scope mismatch'; end if;
  perform pg_advisory_xact_lock(hashtextextended('supplementscout:fit-house-exact-pack:owner-reviewed-24',0));
  select count(*) into v_products_before from public.products; select count(*) into v_variants_before from public.product_variants;
  select count(*) into v_mappings_before from public.retailer_products; select count(*) into v_offers_before from public.offers;
  select count(*) into v_history_before from public.price_history; select count(*) into v_series_before from public.price_identity_series;
  if v_products_before<>1112 or v_variants_before<>2785 or v_mappings_before<>2761 or v_offers_before<>2761 or v_history_before<>4001
    or (select count(*) from public.retailer_products rp join public.product_variants v on v.id=rp.product_variant_id where rp.retailer_id=9 and v.pack_count is not null and v.size_value is not null and nullif(trim(v.size_unit),'') is not null)<>219
    or (select count(*) from public.retailer_products where retailer_id=9)<>286 or (select count(*) from public.offers where retailer_id=9)<>286 then raise exception 'Fit House owner-reviewed exact-pack 24 baseline mismatch'; end if;
  for e in select *,size_value::text||'-servings' target_key,size_value::text||' Servings' target_name from jsonb_to_recordset(v_scope) as x(mode text,product_id bigint,product text,from_variant_id bigint,mapping_id bigint,offer_id bigint,external_product_id text,external_variant_id text,external_sku text,external_options jsonb,url text,variant_key text,display_name text,flavour_code text,flavour_label text,size_value numeric,product_format text,price numeric,shipping numeric,total numeric,in_stock boolean) order by mapping_id loop
    if not exists(select 1 from public.products where id=e.product_id and name=e.product and is_active and merged_into_product_id is null for update)
      or exists(select 1 from public.price_identity_series where offer_id=e.offer_id) then raise exception 'Fit House product or prior-series mismatch for mapping %',e.mapping_id; end if;
    select to_jsonb(rp) into v_mapping_before from public.retailer_products rp where rp.id=e.mapping_id and rp.retailer_id=9 and rp.product_id=e.product_id and rp.product_variant_id=e.from_variant_id and rp.external_product_id=e.external_product_id and rp.external_variant_id=e.external_variant_id and rp.external_sku is not distinct from e.external_sku and coalesce(rp.external_options,'{}'::jsonb)=coalesce(e.external_options,'{}'::jsonb) and rp.external_url=e.url for update;
    select to_jsonb(o) into v_offer_before from public.offers o where o.id=e.offer_id and o.retailer_id=9 and o.product_id=e.product_id and o.product_variant_id=e.from_variant_id and o.retailer_product_id=e.mapping_id and o.price=e.price and o.shipping_cost=e.shipping and o.total_price=e.total and o.in_stock=e.in_stock and o.url=e.url for update;
    if v_mapping_before is null or v_offer_before is null then raise exception 'Fit House binding or commercial mismatch for mapping %',e.mapping_id; end if;
    if e.mode='create' then
      if not exists(select 1 from public.product_variants where id=e.from_variant_id and product_id=e.product_id and variant_key='default' and display_name='Default' and size_value is null and size_unit is null and pack_count is null and is_active and is_default for update)
        or exists(select 1 from public.product_variants where product_id=e.product_id and variant_key=e.target_key) then raise exception 'Fit House create target mismatch for mapping %',e.mapping_id; end if;
      insert into public.product_variants(product_id,variant_key,display_name,flavour_code,flavour_label,size_value,size_unit,pack_count,product_format,gtin,image,nutrition_override,is_default,is_active)
      values(e.product_id,e.target_key,e.target_name,null,null,e.size_value,'servings',1,e.product_format,null,null,'{}'::jsonb,false,true) returning id into v_target_variant_id;
      update public.retailer_products set product_variant_id=v_target_variant_id where id=e.mapping_id and retailer_id=9 and product_variant_id=e.from_variant_id;
      get diagnostics v_rows=row_count; if v_rows<>1 then raise exception 'Fit House mapping move affected % rows',v_rows; end if;
      update public.offers set product_variant_id=v_target_variant_id where id=e.offer_id and retailer_product_id=e.mapping_id and product_variant_id=e.from_variant_id;
      get diagnostics v_rows=row_count; if v_rows<>1 then raise exception 'Fit House offer move affected % rows',v_rows; end if;
      if not exists(select 1 from public.retailer_products rp join public.offers o on o.retailer_product_id=rp.id where rp.id=e.mapping_id and o.id=e.offer_id and rp.product_variant_id=v_target_variant_id and o.product_variant_id=v_target_variant_id and (to_jsonb(rp)-'product_variant_id')=(v_mapping_before-'product_variant_id') and (to_jsonb(o)-'product_variant_id')=(v_offer_before-'product_variant_id')) then raise exception 'Fit House preservation mismatch for mapping %',e.mapping_id; end if;
    elsif e.mode='enrich' then
      if not exists(select 1 from public.product_variants where id=e.from_variant_id and product_id=e.product_id and variant_key=e.variant_key and display_name=e.display_name and flavour_code=e.flavour_code and flavour_label=e.flavour_label and size_value is null and size_unit is null and pack_count=1 and product_format=e.product_format and is_active and not is_default for update)
        or (select count(*) from public.retailer_products where product_variant_id=e.from_variant_id)<>1 or (select count(*) from public.offers where product_variant_id=e.from_variant_id)<>1 then raise exception 'Fit House enrich target mismatch for mapping %',e.mapping_id; end if;
      update public.product_variants set size_value=e.size_value,size_unit='servings' where id=e.from_variant_id and size_value is null and size_unit is null and pack_count=1;
      get diagnostics v_rows=row_count; if v_rows<>1 then raise exception 'Fit House variant enrichment affected % rows',v_rows; end if;
      if not exists(select 1 from public.retailer_products rp join public.offers o on o.retailer_product_id=rp.id where rp.id=e.mapping_id and o.id=e.offer_id and rp.product_variant_id=e.from_variant_id and o.product_variant_id=e.from_variant_id and to_jsonb(rp)=v_mapping_before and to_jsonb(o)=v_offer_before) then raise exception 'Fit House enrich preservation mismatch for mapping %',e.mapping_id; end if;
    else raise exception 'Fit House unsupported mode for mapping %',e.mapping_id; end if;
  end loop;
  if (select count(*) from public.products)<>v_products_before or (select count(*) from public.product_variants)<>v_variants_before+22
    or (select count(*) from public.retailer_products)<>v_mappings_before or (select count(*) from public.offers)<>v_offers_before
    or (select count(*) from public.price_history)<>v_history_before or (select count(*) from public.price_identity_series)<>v_series_before
    or (select count(*) from public.retailer_products rp join public.product_variants v on v.id=rp.product_variant_id where rp.retailer_id=9 and v.pack_count is not null and v.size_value is not null and nullif(trim(v.size_unit),'') is not null)<>243 then raise exception 'Fit House owner-reviewed exact-pack 24 postcondition mismatch'; end if;
end $apply$;

commit;
